def changed_paths(before, after):
    """Return sorted dot-separated paths for additions, removals, or unequal leaves.

    Recurses only where BOTH values are dicts; all other comparisons are atomic.
    """
    paths = []
    _diff(before, after, "", paths)
    return sorted(paths)


def _diff(before, after, prefix, paths):
    for key in set(before) | set(after):
        path = prefix + "." + key if prefix else key
        if key not in after:
            paths.append(path)
        elif key not in before:
            paths.append(path)
        else:
            b_val = before[key]
            a_val = after[key]
            if isinstance(b_val, dict) and isinstance(a_val, dict):
                _diff(b_val, a_val, path, paths)
            elif b_val != a_val:
                paths.append(path)
