def delays(attempts, base, cap):
    """Return a list of retry delays with exponential backoff."""
    if not isinstance(attempts, int) or not isinstance(base, int) or not isinstance(cap, int):
        raise ValueError("All arguments must be integers")
    if attempts < 1:
        raise ValueError("attempts must be >= 1")
    if base < 0:
        raise ValueError("base must be >= 0")
    if cap < 0:
        raise ValueError("cap must be >= 0")

    return [min(base * (2 ** i), cap) for i in range(attempts - 1)]
