def unique_latest(records):
    first_order = []
    best = {}
    for record in records:
        rid = record['id']
        if rid not in best:
            first_order.append(rid)
            best[rid] = record
        else:
            if record['timestamp'] >= best[rid]['timestamp']:
                best[rid] = record
    return [best[rid] for rid in first_order]
