import copy


def merge(base, overlay):
    """Recursively merge two dictionaries into a deep-independent result.

    - Overlay values replace base values.
    - If both values are dicts, merge them recursively.
    - Otherwise (including lists, None, scalars), the overlay value wins.
    - A None value in the overlay sets the key to None; it does not delete it.
    - The returned dict is independent of both inputs (no aliasing).
    """
    result = {}
    all_keys = set(base) | set(overlay)
    for key in all_keys:
        if key in base and key in overlay:
            if isinstance(base[key], dict) and isinstance(overlay[key], dict):
                result[key] = merge(base[key], overlay[key])
            else:
                result[key] = copy.deepcopy(overlay[key])
        elif key in overlay:
            result[key] = copy.deepcopy(overlay[key])
        else:
            result[key] = copy.deepcopy(base[key])
    return result
```

