def flatten(value):
    """Flatten nested dictionaries with string keys into dot-separated keys.

    - Non-empty dicts are recursed into.
    - Empty dicts are preserved as {} leaves.
    - Lists and scalars are preserved as-is.
    - The input is not mutated.
    """
    result = {}
    _flatten(value, "", result)
    return result


def _flatten(d, prefix, result):
    for key, val in d.items():
        new_key = f"{prefix}.{key}" if prefix else key
        if isinstance(val, dict) and len(val) > 0:
            _flatten(val, new_key, result)
        else:
            result[new_key] = val
